-- Who opened a claim: set when it is opened, null while it is DRAFT. Its opener may not settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
-- How many times a person has been saved since added. An edit names the version it loaded and is
-- refused when the person has been saved since (someone else's edit in the meantime).
ALTER TABLE person ADD COLUMN version INT NOT NULL DEFAULT 0;
-- One row per sheet that has been loaded. `today` is the sheet's own date: every date-dependent
-- decision and every default date on the sheet uses it, never the real clock.
CREATE TABLE sheet (
    id    VARCHAR(200) PRIMARY KEY,
    today DATE         NOT NULL
);
-- The people on a sheet, listed in the order they were added (by id). `grade` is one of A, B, C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    name     VARCHAR(500) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person's name is unique on its sheet, compared without case and ignoring surrounding spaces.
-- Names are stored trimmed; `name_key` is the form they are compared in.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(500) GENERATED ALWAYS AS (LOWER(TRIM(name)));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A person's claims, listed newest first (by id). `amount` is 0.00 or more, two decimals;
-- `claim_date` defaults to the sheet's today when the claim is made; `note` may be empty.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)  NOT NULL,
    person_id  BIGINT        NOT NULL REFERENCES person (id),
    amount     DECIMAL(14,2) NOT NULL CHECK (amount >= 0),
    claim_date DATE          NOT NULL,
    note       VARCHAR(2000) NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- The rate for each grade on a sheet: a percent, 0.00 or more, two decimals. A grade with no row
-- has no rate, so its claims' due is n/a. Setting a grade's rate again replaces it.
CREATE TABLE rate (
    sheet_id VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL,
    pct      DECIMAL(7,2) NOT NULL CHECK (pct >= 0),
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's status: DRAFT when made, then OPEN, then SETTLED; a DRAFT or OPEN claim can go VOID.
-- Only OPEN and SETTLED claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL;
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), with no gaps and
-- never reused. A DRAFT has none; voiding a claim clears it. `sheet.claim_numbers` is how many
-- numbers the sheet has given out, so the next one is claim_numbers + 1.
ALTER TABLE claim ADD COLUMN number BIGINT;
ALTER TABLE sheet ADD COLUMN claim_numbers BIGINT DEFAULT 0 NOT NULL;
UPDATE claim c SET number = (SELECT COUNT(*) FROM claim d WHERE d.sheet_id = c.sheet_id
    AND d.status IN ('OPEN', 'SETTLED') AND d.id <= c.id) WHERE status IN ('OPEN', 'SETTLED');
UPDATE sheet s SET claim_numbers = (SELECT COUNT(*) FROM claim c WHERE c.sheet_id = s.id
    AND c.status IN ('OPEN', 'SETTLED'));
CREATE UNIQUE INDEX claim_sheet_number ON claim (sheet_id, number);
-- A claim's due, fixed when it is settled: amount times its person's grade's rate then, divided
-- by 100, rounded half up to two decimals. Null while the claim is not settled, or when it was
-- settled with no rate (n/a): such a claim's due stays live, at the current rate.
ALTER TABLE claim ADD COLUMN due DECIMAL(14,2);
-- A rate can carry a from-date: a grade may have several rates, and a claim uses the one whose
-- from-date is the latest on or before the claim's date. A rate with no from-date (null) applies
-- from the beginning of time. Setting a rate for a grade and from-date that already exist replaces
-- it; `from_key` is the from-date as compared for that, with null as the earliest date.
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim a person on a sheet has made, DRAFT (and unnumbered) until it is opened. `id` is null until the claim is first saved. */
public class Claim {
    private Long id;
    private final String sheetId;
    private final long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private Long number;
    private BigDecimal due;
    private String openedBy;

    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, Long number, BigDecimal due, String openedBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.due = due;
        this.openedBy = openedBy;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public ClaimStatus getStatus() { return status; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    /** The claim's number on its sheet, given when it is opened; null for a DRAFT or VOID claim. */
    public Long getNumber() { return number; }
    public void setNumber(Long number) { this.number = number; }
    /** The due fixed when the claim was settled; null when it has none (not settled, or settled with no rate). */
    public BigDecimal getDue() { return due; }
    public void setDue(BigDecimal due) { this.due = due; }
    /** The user who opened the claim; null while it has not been opened. */
    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
}
package net.officefloor.hq.app.claim;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims of each sheet, newest first. */
@Repository
public class Claims {

    private static final String COLUMNS = "SELECT id, sheet_id, person_id, amount, claim_date, note, status, number, due, opened_by FROM claim";

    private final JdbcTemplate jdbc;

    public Claims(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Claim> onSheet(String sheetId) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? ORDER BY id DESC", Claims::claim, sheetId);
    }

    /** The claim with this id on this sheet, or null when there is none. Locks the claim's row for
     *  the rest of the transaction, so two changes to one claim at once happen one after the other. */
    public Claim find(String sheetId, long id) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND id = ? FOR UPDATE", Claims::claim, sheetId, id)
                .stream().findFirst().orElse(null);
    }

    /** Insert a new claim (assigning its id) or update an existing one. */
    public void save(Claim claim) {
        if (claim.getId() != null) {
            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, due = ?, opened_by = ? WHERE id = ?",
                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
                    claim.getNumber(), claim.getDue(), claim.getOpenedBy(), claim.getId());
            return;
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status) VALUES (?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, claim.getSheetId());
            ps.setLong(2, claim.getPersonId());
            ps.setBigDecimal(3, claim.getAmount());
            ps.setDate(4, Date.valueOf(claim.getDate()));
            ps.setString(5, claim.getNote());
            ps.setString(6, claim.getStatus().name());
            return ps;
        }, keys);
        claim.setId(keys.getKey().longValue());
    }

    private static Claim claim(ResultSet rs, int i) throws SQLException {
        return new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
                rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
                ClaimStatus.valueOf(rs.getString("status")), rs.getObject("number", Long.class),
                rs.getBigDecimal("due"), rs.getString("opened_by"));
    }
}
